// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Keep domain wide but require _tos non-empty because original function requires it
        vm.assume(_tos.length > 0);
        // As noted, low-level call is made to caddress; a fuzzed address would be EOA (call succeeds and returns true)
        // We only need to observe the return boolean of c.transfer; wrap in try/catch to read whether it returned true/false
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, mark as false — but original contract only reverts when _tos.length == 0 which we've excluded
            ok = false;
        }
        // The universal property: for all admissible inputs (with _tos.length>0) reference returns true; mutant returns false for some inputs.
        // Assert that c.transfer(...) returned true (this will pass on the reference and fail on the mutant for inputs the fuzzer finds)
        assertTrue(ok);
    }
}
